// Draws the UML diagrams used by README.md / docs/ARCHITECTURE.md and writes them to docs/img/*.png.
//   node tools/diagrams/build.mjs            (npm run docs:diagrams)      -> all diagrams
//   node tools/diagrams/build.mjs startup    -> only diagrams whose name contains "startup"
// Pure Node: SVG is generated by tools/diagrams/lib.mjs and rasterised by sharp (already a dependency). No browser, no Java, no downloads.
// When the code architecture changes, edit the matching function below and re-run.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import sharp from 'sharp';
import { Canvas, COL, sequence, tw } from './lib.mjs';

const OUT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../docs/img');
fs.mkdirSync(OUT, { recursive: true });
const D = {};

// ====================================================================================================================================
// 1. Component overview
// ====================================================================================================================================
D['01-components'] = () => {
  const c = new Canvas(1580, 900, 'Yerevan Drift: component overview (browser runtime)');

  // ---- core
  c.pkg(30, 70, 1140, 190, 'Core: src/main.js and services', COL.core + '66');
  c.box(50, 100, 280, 140, { title: 'main.js', stereo: 'entry point', fill: COL.core, lines: ['renderer · scene · camera · lights', 'camera modes: orbit / fly / tour / drive', 'time of day, street-lamp light pool', 'frame loop (setAnimationLoop)'] });
  c.box(345, 100, 190, 140, { title: 'quality.js', stereo: 'module', fill: COL.core, lines: ['presets low / med / high / ultra', 'GPU auto-detect, ?q= override', 'crash flag, safe mode'] });
  c.box(550, 100, 195, 140, { title: 'perf.js  Governor', stereo: 'module', fill: COL.core, lines: ['CPU- or GPU-bound?', 'lowers resolution, shadows, fx', 'climbs back when there is room'] });
  c.box(760, 100, 165, 140, { title: 'net.js', stereo: 'module', fill: COL.core, lines: ['fetchJSON / fetchBuffer', 'request de-duplication', 'warmStartup()'] });
  c.box(940, 100, 210, 140, { title: 'materials · pbr', stereo: 'modules', fill: COL.core, lines: ['PBR materials, wet asphalt', 'textures.js, facadeAtlas.js', 'shared uniforms (uDay, wetness)'] });

  // ---- plug-ins
  c.pkg(30, 330, 1140, 270, 'Plug-ins', COL.plug + '55');
  c.text(200, 352, 'src/*.js, found with import.meta.glob(...)  ->  default export  async (ctx) => ({ update(dt, camera, time) })', { size: 12, italic: true, fill: '#6b5a2a' });
  const P = [
    ['landmarks.js', ['hand-modelled Republic Sq.', 'Opera, Cathedral, fountain', 'src/landmarks/*']],
    ['props.js', ['trees, street furniture, signs', 'instanced LOD, wind', 'src/props/*']],
    ['orbeli.js', ['Orbeli Bros St + Komitas Ave', 'procedural facades', 'src/streets/*']],
    ['car.js', ['Rapier + custom tyre model', 'garage: M2 · P1 · Countach', 'src/car/*']],
    ['circuits.js', ['race circuits and barriers', 'off by default (?circuits=1)', 'src/circuits/*']],
    ['menu.js', ['nickname, menu, garage', 'driver / spectator roles', 'camera owner while open']],
    ['mp.js', ['ghost-car multiplayer', 'Trystero WebRTC, 15 Hz', 'no backend needed']],
    ['nav.js', ['2D map + GPS navigator', 'search, routing, minimap', 'src/nav/*']],
  ];
  P.forEach(([t, l], i) => c.box(50 + (i % 4) * 275, 366 + Math.floor(i / 4) * 118, 255, 104, { title: t, stereo: 'plug-in', fill: i === 4 ? '#f7f3e8' : COL.plug, dashed: i === 4, lines: l }));

  // ---- world
  c.pkg(30, 660, 1140, 200, 'World and rendering', COL.world + '66');
  c.box(50, 690, 250, 150, { title: 'world/streamer.js', stereo: 'Streamer', fill: COL.world, lines: ['quadtree LOD tiles L0 .. L4', 'coarse levels stay resident', 'prefetch() before teleports', 'time-sliced attach'] });
  c.box(315, 690, 200, 150, { title: 'world/batches.js', stereo: 'TileBatches', fill: COL.world, lines: ['BatchedMesh per material', 'slot recycling', '954 -> ~370 draw calls'] });
  c.box(530, 690, 205, 150, { title: 'sky.js', stereo: 'modules', fill: COL.world, lines: ['night / dusk / day dome', 'volumetric clouds', 'skyClouds.js, skyNoise.js'] });
  c.box(750, 690, 400, 150, { title: 'post/*  +  world/probe.js', stereo: 'render chain', fill: COL.world, lines: ['Render -> SceneFX -> Bloom -> Final', 'SceneFX: AO, SSR, ray-traced fallback', 'rtworld + worker: city heightfield bake', 'cloudpass, live reflection probe'] });

  // ---- external column
  c.pkg(1300, 70, 250, 190, 'External libraries', '#f4f4f4');
  c.box(1320, 100, 210, 44, { title: 'three.js', fill: COL.ext });
  c.box(1320, 152, 210, 44, { title: 'Rapier (WASM)', fill: COL.ext });
  c.box(1320, 204, 210, 44, { title: 'Trystero (WebRTC)', fill: COL.ext });
  c.pkg(1300, 330, 250, 530, 'Static assets: public/', COL.asset + '66');
  const A = [['tiles/', ['L0..L4 *.glb, manifest.json', 'pack34.bin (horizon)']], ['map/', ['meta, props, nav, surface,', 'colliders, aerial *.webp']], ['car/', ['bmw_m2, mclaren_p1,', 'countach  (*.glb + *.json)']], ['tex/', ['PBR sets, road field']], ['audio/', ['engine loops *.wav']]];
  A.forEach(([t, l], i) => c.file(1320, 366 + i * 96, 210, 80, { title: t, lines: l }));

  // ---- relations
  c.arrow([[240, 240], [240, 330]], { head: 'filled', label: 'default(ctx)', dx: 50, at: 0.5 });
  c.arrow([[330, 330], [330, 240]], { head: 'open', dashed: true, label: 'update(dt, camera, time)', dx: 88, at: 0.5 });
  c.arrow([[50, 170], [38, 170], [38, 735], [50, 735]], { head: 'filled' });
  c.label(46, 640, 'preload() · update(camera) · prefetch()', { anchor: 'start', size: 11 });
  c.arrow([[1170, 150], [1300, 150]], { head: 'open', dashed: true, label: 'imports', at: 0.5 });
  c.arrow([[1170, 345], [1300, 226]], { head: 'open', dashed: true, label: 'Rapier · Trystero', at: 0.45, dx: -30, dy: -8 });
  c.arrow([[1170, 470], [1300, 470]], { head: 'open', dashed: true, label: 'fetch', at: 0.5 });
  c.arrow([[1170, 760], [1300, 760]], { head: 'open', dashed: true, label: 'fetch tiles', at: 0.5 });
  c.arrow([[300, 765], [315, 765]], { head: 'filled' });
  c.note(560, 266, 560, ['ctx = { THREE, scene, renderer, camera, M, T, meta, H, lampHeads, tod, drive }  (shared with every plug-in)']);
  return c;
};

// ====================================================================================================================================
// 2. Start-up sequence
// ====================================================================================================================================
D['02-startup-sequence'] = () => {
  const c = new Canvas(1460, 1010, 'Start-up sequence (src/main.js)');
  const parts = [
    { id: 'br', label: 'Browser', stereo: 'index.html', fill: COL.ext }, { id: 'main', label: 'main.js' }, { id: 'svc', label: 'quality · net', stereo: 'services' },
    { id: 'st', label: 'Streamer', fill: COL.world }, { id: 'fx', label: 'SceneFXPass', fill: COL.world }, { id: 'pl', label: 'Plug-ins', fill: COL.plug }, { id: 'gl', label: 'WebGL', stereo: 'renderer', fill: COL.ext },
  ];
  c.h = sequence(c, { x0: 100, y0: 56, gap: 210, parts, boxW: 140, steps: [
    { m: ['br', 'main', 'load <script type=module>'] },
    { m: ['main', 'svc', 'bootStart() · warmStartup()'] },
    { self: ['main', 'renderer, scene, sky, lights, EffectComposer'] },
    { m: ['main', 'svc', 'fetchJSON(meta.json, manifest.json)'] },
    { m: ['svc', 'main', 'metadata', ], dashed: true },
    { m: ['main', 'st', 'new Streamer() · preload(camera)'] },
    { m: ['st', 'svc', 'fetch pack34.bin + near tiles'] },
    { m: ['st', 'main', 'progress(p)  (loading bar)'], dashed: true },
    { m: ['main', 'svc', 'loadHeight()  (9 MB grid)'] },
    { m: ['main', 'fx', 'new SceneFXPass(heightGrid), insertPass(1)'] },
    { m: ['main', 'fx', 'initRTWorld()  (worker bake, background)'], dashed: true },
    { open: 'par', label: 'phase 1: nothing needs the car', from: 'main', to: 'pl' },
    { m: ['main', 'pl', 'landmarks · props · orbeli · car  ->  default(ctx)'] },
    { m: ['pl', 'main', '{ update }'], dashed: true },
    { close: true },
    { open: 'par', label: 'phase 2: needs the car', from: 'main', to: 'pl' },
    { m: ['main', 'pl', 'menu · mp  ->  default(ctx)'] },
    { m: ['pl', 'main', '{ update }'], dashed: true },
    { close: true },
    { m: ['main', 'pl', 'nav  ->  default(ctx)   (not awaited)'] },
    { self: ['main', 'sort plug-in updates by file name'] },
    { m: ['main', 'gl', 'compileAsync(scene, camera)   (max 20 s)'] },
    { self: ['main', 'hide loading screen · bootDone() · createGovernor()'] },
    { m: ['main', 'gl', 'setAnimationLoop(frame)'] },
    { note: ['pl', 'pl', ['nav finishes behind the', 'loading screen (1.4 MB graph)']] },
  ] }) + 30;
  return c;
};

// ====================================================================================================================================
// 3. Frame loop sequence
// ====================================================================================================================================
D['03-frame-sequence'] = () => {
  const c = new Canvas(1790, 960, 'One frame (setAnimationLoop in main.js, car physics in car.js)');
  const parts = [
    { id: 'lp', label: 'frame()', stereo: 'main.js' }, { id: 'cam', label: 'Camera mode', fill: COL.core }, { id: 'pl', label: 'Other plug-ins', fill: COL.plug },
    { id: 'car', label: 'car.js', fill: COL.plug }, { id: 'veh', label: 'Vehicle', fill: COL.plug }, { id: 'rp', label: 'Rapier World', fill: COL.ext },
    { id: 'st', label: 'Streamer', fill: COL.world }, { id: 'gv', label: 'Governor', fill: COL.core }, { id: 'fx', label: 'SceneFXPass', fill: COL.world }, { id: 'co', label: 'EffectComposer', fill: COL.ext },
  ];
  c.h = sequence(c, { x0: 90, y0: 56, gap: 162, parts, boxW: 130, steps: [
    { self: ['lp', 'dt, fitSize(), ease time of day'] },
    { m: ['lp', 'cam', 'orbit / fly / tour / camUpdate'] },
    { self: ['lp', 'lamp lights (every 0.15 s)'] },
    { open: 'loop', label: 'every plug-in, sorted by file name', from: 'lp', to: 'rp' },
    { m: ['lp', 'pl', 'update(dt, camera, time)'] },
    { m: ['lp', 'car', 'update(dt, camera, time)'] },
    { open: 'alt', label: 'drive.active', from: 'car', to: 'rp' },
    { open: 'loop', label: 'while acc >= 1/120 s (max 8)', from: 'car', to: 'rp' },
    { m: ['car', 'veh', 'step(DT)'] },
    { m: ['veh', 'rp', 'world.step()'] },
    { m: ['rp', 'veh', 'contacts, impact'], dashed: true },
    { close: true },
    { m: ['car', 'veh', 'transform(alpha) -> root'] },
    { self: ['car', 'colliders, skids, smoke, audio, HUD'] },
    { self: ['car', 'chase camera, drive.focus'] },
    { close: true },
    { close: true },
    { self: ['lp', 'shadow window follows focus'] },
    { m: ['lp', 'gv', 'update(dt, cpuMs)'] },
    { m: ['lp', 'st', 'update(camera.position)'] },
    { m: ['lp', 'fx', 'update({ sun, fog, ... })'] },
    { m: ['lp', 'co', 'render()'] },
    { self: ['co', 'Render > SceneFX > Bloom > Final'] },
    { note: ['car', 'veh', ['Rapier owns the rigid body and collisions;', 'tyres, engine, gearbox are our own code.']] },
  ] }) + 30;
  return c;
};

// ====================================================================================================================================
// 4. Class diagram: drivable car
// ====================================================================================================================================
D['04-class-car'] = () => {
  const c = new Canvas(1480, 960, 'Class diagram: drivable car (src/car.js + src/car/*)');
  const plug = c.cls(40, 70, 310, { name: 'car.js', stereo: 'plug-in', fill: COL.plug,
    attrs: ['world: RAPIER.World', 'vehicle: Vehicle', 'entries: Map<id, GLB>', 'paintMat, heads: SpotLight[]', 'spawn, safe: {x,z,heading}'],
    ops: ['update(dt, camera, time)', 'respawn(to)', 'setCar(id)', 'makeRemote(paint, car)', 'loadEntry(id)'] });
  const veh = c.cls(470, 70, 400, { name: 'Vehicle', fill: COL.core,
    attrs: ['body: RigidBody  (Rapier)', 'wheels: Wheel[4]   FL FR RL RR', 'input: throttle, brake, steer, handbrake', 'gear, rpm, auto, abs, tcs, steerAssist', 'pos, quat, vel, up, fwd: Vector3', 't: speed, kmh, beta, yawRate, gLat', 'impact, scrape, flipT'],
    ops: ['build()          colliders, mass, wheels', 'setProfile(id)', 'reset(x, z, heading, y)', 'step(dt)          fixed 1/120 s', 'transform(alpha, pos, quat)', 'maxSteer(speed)'] });
  const whl = c.cls(990, 70, 330, { name: 'Wheel', stereo: 'plain object', fill: COL.core,
    attrs: ['key: FL | FR | RL | RR', 'front, left: boolean', 'omega, spin, steer', 'd: suspension compression', 'contact, fz', 'slip, slipX, slipY', 'surf: SURF code', 'pcx, pcy, pcz: contact point'] });
  const prof = c.cls(990, 440, 330, { name: 'CarProfile', stereo: 'CAR_PROFILES[id]', fill: COL.asset,
    attrs: ['name, sub, file (GLB)', 'phys.mass, inertia, hCOM, zCOM', 'phys.axleF / axleR, kF / kR', 'phys.muF / muR, torque[], ratios[]', 'phys.box / cabin (collision)', 'ids: bmw_m2, mclaren_p1, countach'],
    ops: ['applyProfile(id)   mutates CAR'] });
  const ground = c.cls(40, 440, 300, { name: 'Ground', stereo: 'createGround(H)', fill: COL.world,
    attrs: ['height grid H(x, z), 5 m', 'surface raster, 0.5 m cells'],
    ops: ['y(x, z)', 'surface(x, z): SURF', 'mu(x, z)', 'normal(x, z, out)', 'inBounds(x, z)'] });
  const col = c.cls(400, 440, 300, { name: 'Colliders', stereo: 'createColliders()', fill: COL.world,
    attrs: ['cells: Map  (96 m buckets)'], ops: ['update(px, pz, budget)', 'prime(px, pz)', 'setEnabled(e)'] });
  const rapier = c.cls(735, 440, 175, { name: 'RAPIER.World', stereo: 'external', fill: COL.ext, ops: ['step()', 'castRay(...)', 'createCollider(...)'] });

  const row3 = 760, bus = 720;
  const input = c.cls(40, row3, 250, { name: 'Input', stereo: 'createInput()', ops: ['pollPad()', 'update(dt, vehicle)', 'rumble(weak, strong)', 'reset()'] });
  const camr = c.cls(315, row3, 250, { name: 'CarCamera', stereo: 'createCarCamera()', ops: ['update(dt, pos, quat, ...)', 'cycle()  CHASE FAR HOOD COCKPIT', 'impact(v)', 'reset()'] });
  const hud = c.cls(590, row3, 250, { name: 'Hud', stereo: 'createHud()', ops: ['update(dt, state)', 'toast(text, s)', 'resetScore()', 'show(on)'] });
  const aud = c.cls(865, row3, 250, { name: 'Audio', stereo: 'createAudio()', ops: ['update({ rpm, slip, ... })', 'impact(v)', 'toggleMute()', 'resume()'] });
  const fxc = c.cls(1140, row3, 300, { name: 'Skids · Smoke · Sparks', stereo: 'car/fx.js', ops: ['feed(i, x, z, intensity)', 'emit(i, dt, ...)', 'burst(x, y, z, ...)', 'update(dt)'] });

  // car.js owns the helpers (composition) via two buses on the left margin
  c.arrow([[40, 150], [22, 150], [22, 420], [190, 420], [190, 440]], { head: null, tail: 'diamond' });
  c.arrow([[22, 420], [550, 420], [550, 440]], { head: null });
  c.arrow([[22, 420], [22, bus], [1290, bus], [1290, row3]], { head: null });
  for (const r of [input, camr, hud, aud]) c.arrow([[r.cx, bus], [r.cx, row3]], { head: null });
  c.label(36, 405, 'owns', { anchor: 'start', size: 10.5 });
  c.arrow([[350, 150], [470, 150]], { head: null, tail: 'diamond', label: '1', dy: -8 });
  c.arrow([[870, 150], [990, 150]], { head: null, tail: 'diamond', label: '4', dy: -8 });
  c.arrow([[870, 250], [950, 250], [950, 520], [990, 520]], { head: 'open', dashed: true, label: '«uses»', at: 0.45, dx: 0, dy: -8 });
  c.arrow([[560, veh.b], [560, 385], [270, 385], [270, 440]], { head: 'open', dashed: true, label: 'y(), surface(), mu()', at: 0.5 });
  c.arrow([[760, veh.b], [760, 395], [rapier.cx, 395], [rapier.cx, 440]], { head: 'open', dashed: true });
  c.label(rapier.cx + 10, 383, 'body, step()', { size: 10.5 });
  c.arrow([[700, 520], [735, 520]], { head: 'open', dashed: true });
  c.note(40, plug.b + 16, 300, ['car.js wires everything together and', 'exposes drive.car (vehicle, ground,', 'hud, setCar, teleport, netState ...)', 'for the menu, map and multiplayer.']);
  c.note(990, 640, 330, ['Frame: x = car left, y up, z forward,', 'body origin = centre of mass.']);
  return c;
};

// ====================================================================================================================================
// 5-7. class diagram (plug-ins / streaming), state machine, data pipeline
// ====================================================================================================================================
D['05-class-world'] = () => {
  const c = new Canvas(1500, 1130, 'Class diagram: plug-in contract, streaming, post chain, navigator');
  const plugin = c.cls(40, 70, 440, { name: 'Plugin', stereo: 'interface', fill: COL.plug, abstract: true, ops: ['default(ctx): Promise<{ update?(dt, camera, time) }>'] });
  const impl = c.cls(40, 185, 440, { name: 'Plug-in files in src/', fill: COL.plug, attrs: ['landmarks · props · orbeli · circuits', 'car · menu · mp · nav'] });
  const ctx = c.cls(560, 70, 460, { name: 'ctx', stereo: 'PluginContext', fill: COL.core,
    attrs: ['THREE, scene, renderer, camera', 'M, T: materials, textures', 'meta: map metadata (lamps, neon, places)', 'H(x, z): terrain height', 'lampHeads: Vector3[]', 'tod: { day, night }', 'drive: DriveState'] });
  const drive = c.cls(560, 330, 460, { name: 'drive', stereo: 'DriveState', fill: COL.core,
    attrs: ['active, wanted, uiLock, menuOn', 'focus: Vector3   shadow + lamps + streaming', 'car: { vehicle, ground, hud, setCar, ... }', 'players[], camUpdate, startMode'],
    ops: ['set(on) / setMode(mode)', 'lookAt(x, z, dist)', 'prefetch(x, z)', 'toggleRole()'] });
  const streamer = c.cls(1090, 70, 380, { name: 'Streamer', fill: COL.world,
    attrs: ['nodes: Map<"L_i_j", TileNode>', 'roots, queue, pinQueue, pending', 'pinLevel  (2, or 3 on Low)', 'pack: pack34.bin index', 'batches: TileBatches', 'hints, burstUntil'],
    ops: ['preload(pos, onProgress)', 'update(pos)', 'prefetch(x, z, y)', 'select / resolve / keepCover', 'fetchTile / pump / flushPending', 'beginAttach / stepAttach / evict'] });
  const node = c.cls(1090, 390, 380, { name: 'TileNode', stereo: 'plain object', fill: COL.world,
    attrs: ['L, i, j, S = 256 * 2^L m', 'minY, maxY', "state: 'idle' | 'loading' | 'loaded'", 'group, parent, kids[4], shown'] });
  const batch = c.cls(1090, 580, 380, { name: 'TileBatches', fill: COL.world, attrs: ['one BatchedMesh per material', 'free slots, grow / compact'],
    ops: ['get(material, geo, ...)', 'add(material, geo, matrix, opts)', 'setVisible(handle, v)', 'release(handle)', 'ensure(b, nVerts, nIdx)'] });

  const pass = c.cls(40, 420, 300, { name: 'Pass', stereo: 'three.js', fill: COL.ext, abstract: true, ops: ['render(renderer, write, read)', 'setSize(w, h)'] });
  const sfx = c.cls(40, 640, 270, { name: 'SceneFXPass', fill: COL.world, attrs: ['depthTexture, heightGrid', 'half-res AO + reflections', 'ray-traced fallback'], ops: ['update(params)'] });
  const fin = c.cls(330, 640, 270, { name: 'FinalPass', fill: COL.world, attrs: ['tone map, grade', 'vignette, grain, CA'], ops: ['(replaces OutputPass)'] });
  const cld = c.cls(620, 640, 270, { name: 'CloudComposite', fill: COL.world, attrs: ['volumetric clouds over', 'the scene above 1.8 km'], ops: ['render(...)'] });

  const navp = c.cls(40, 900, 300, { name: 'nav.js', stereo: 'plug-in', fill: COL.plug, attrs: ['nav, search, mapper', 'route, dest, prog'], ops: ['update(dt, camera, time)', 'setOpen(on)'] });
  const nav = c.cls(420, 900, 270, { name: 'Nav', fill: COL.plug, attrs: ['road graph, names', 'ways, nodes'], ops: ['snap(x, z)', 'streetAt(x, z)', 'route(from, to)', 'maneuvers(route)'] });
  const sea = c.cls(720, 900, 270, { name: 'Search', fill: COL.plug, attrs: ['street / POI index'], ops: ['query(q, ox, oz)', 'chip(i, ox, oz)', 'reverse(x, z)', 'poiAt(x, z, maxD)'] });
  const mv = c.cls(1020, 900, 300, { name: 'MapRenderer', fill: COL.plug, attrs: ['vector cache, satellite'], ops: ['buildCache(done)', 'loadSat(cb)', 'draw(ctx, W, H, view)'] });

  c.arrow([[impl.cx, impl.y], [plugin.cx, plugin.b]], { head: 'tri', dashed: true, label: 'realize', dx: 36, dy: 4 });
  c.arrow([[480, 120], [560, 120]], { head: 'open', dashed: true, label: 'receive', at: 0.5 });
  c.arrow([[790, ctx.b], [790, 330]], { head: null, tail: 'diamond', label: 'drive', dx: 26, dy: 0 });
  c.arrow([[1280, streamer.b], [1280, node.y]], { head: 'open', tail: 'diamond', label: '1..*', dx: 28, dy: 0 });
  c.arrow([[1470, 200], [1490, 200], [1490, 700], [1470, 700]], { head: 'open', tail: 'diamond' });
  c.label(1488, 450, 'owns', { size: 10.5, anchor: 'end' });
  c.arrow([[drive.r, 460], [1060, 460], [1060, 250], [1090, 250]], { head: 'open', dashed: true });
  c.label(1040, 452, 'prefetch()', { size: 10.5, anchor: 'end' });
  const bus1 = 600;
  c.arrow([[sfx.cx, sfx.y], [sfx.cx, bus1], [190, bus1], [190, pass.b]], { head: 'tri' });
  c.arrow([[fin.cx, fin.y], [fin.cx, bus1], [190, bus1]], { head: null });
  c.arrow([[cld.cx, cld.y], [cld.cx, bus1], [fin.cx, bus1]], { head: null });
  const bus2 = 860;
  c.arrow([[navp.cx, navp.y], [navp.cx, bus2], [mv.cx, bus2], [mv.cx, mv.y]], { head: null, tail: 'diamond' });
  for (const k of [nav, sea]) c.arrow([[k.cx, bus2], [k.cx, k.y]], { head: null });
  c.note(1090, 790, 380, ['TileBatches copies streamed tile', 'geometry into shared multi-draw', 'batches (fewer draw calls).']);
  c.note(40, 800, 560, ['Pass order: Render > SceneFX > Bloom > Final.', 'CloudComposite runs when the camera is above the cloud layer.']);
  return c;
};

D['06-states'] = () => {
  const c = new Canvas(1460, 740, 'State machine: front-end (menu.js) and camera modes (main.js setMode)');
  c.pkg(30, 80, 700, 620, 'Front-end: menu.js', '#faf6ee');
  c.pkg(790, 80, 640, 620, 'Camera mode: main.js setMode()', '#f1f6fc');
  const S = (x, y, w, h, t, sub, f = COL.plug) => c.box(x, y, w, h, { title: t, lines: sub ? [sub] : [], fill: f, round: 22 });
  c.initial(70, 142);
  const nick = S(100, 120, 170, 44, 'Nickname');
  const main = S(330, 120, 170, 44, 'Main menu');
  const play = S(560, 120, 140, 44, 'Play');
  const set = S(100, 250, 170, 44, 'Settings');
  const gar = S(330, 250, 170, 44, 'Garage');
  const drv = S(560, 400, 140, 60, 'Driver', 'drive mode');
  const spc = S(560, 540, 140, 60, 'Spectator', 'free / follow');
  c.arrow([[78, 142], [100, 142]], { head: 'filled' });
  c.arrow([[nick.r, 142], [main.x, 142]], { head: 'filled', label: 'continue', dy: -8 });
  c.arrow([[main.r, 134], [play.x, 134]], { head: 'filled', label: 'Play', dy: -8 });
  c.arrow([[main.cx + 30, main.b], [gar.cx + 30, gar.y]], { head: 'filled', label: 'Garage', dx: 28, dy: 4 });
  c.arrow([[main.cx - 30, gar.y], [main.cx - 30, main.b]], { head: 'filled', label: 'Esc', dx: -22, dy: 4 });
  c.arrow([[main.x + 20, main.b], [main.x + 20, 207], [set.cx, 207], [set.cx, set.y]], { head: 'filled', label: 'Settings', at: 0.6, dy: -8 });
  c.arrow([[play.cx, play.b], [drv.cx, drv.y]], { head: 'filled', label: 'Driver', dx: 30, dy: 0 });
  c.arrow([[play.r - 6, play.b], [play.r - 6, 330], [715, 330], [715, 570], [spc.r, 570]], { head: 'filled', label: 'Spectator', at: 0.45, dx: -6, dy: -8 });
  c.arrow([[drv.x + 25, drv.b], [drv.x + 25, spc.y]], { head: 'filled', label: 'Tab', dx: -20, dy: 0 });
  c.arrow([[drv.r - 25, spc.y], [drv.r - 25, drv.b]], { head: 'filled', label: 'Tab', dx: 20, dy: 0 });
  c.arrow([[drv.x, drv.cy], [532, drv.cy], [532, 156], [main.r, 156]], { head: 'filled' });
  c.arrow([[spc.x, spc.cy], [532, spc.cy], [532, drv.cy]], { head: null });
  c.label(520, 470, 'Esc: open menu', { size: 11, anchor: 'end' });
  c.note(60, 620, 620, ['Esc in the menu resumes the role you left (startPlay(session)).', 'With ?menu=0 there is no menu: the game starts straight in drive mode.']);

  const o = S(850, 140, 160, 44, 'ORBIT', 'key 1', COL.core);
  const f = S(1180, 140, 160, 44, 'FLY', 'key 2', COL.core);
  const t = S(850, 380, 160, 44, 'TOUR', 'key 3', COL.core);
  const d = S(1180, 380, 160, 44, 'DRIVE', 'key 4', COL.core);
  const m = S(1015, 540, 170, 44, 'CUSTOM', 'menu / follow cam', COL.core);
  c.initial(830, 162);
  c.arrow([[838, 162], [850, 162]], { head: 'filled' });
  c.arrow([[o.r, 150], [f.x, 150]], { head: 'filled', label: '2', dy: -6 });
  c.arrow([[f.x, 176], [o.r, 176]], { head: 'filled', label: '1', dy: 14 });
  c.arrow([[o.cx, o.b], [t.cx, t.y]], { head: 'filled', label: '3', dx: 12 });
  c.arrow([[f.cx, f.b], [d.cx, d.y]], { head: 'filled', label: '4', dx: 12 });
  c.arrow([[t.r, 402], [d.x, 402]], { head: 'filled', label: '4', dy: -6 });
  c.arrow([[d.cx - 40, d.b], [m.r - 40, m.y]], { head: 'filled', label: 'menu opens', at: 0.5, dx: -64, dy: 0 });
  c.arrow([[m.r, 570], [1300, 570], [1300, d.b]], { head: 'filled', label: 'Driver role', at: 0.55, dx: 10, dy: 16 });
  c.note(850, 620, 560, ['Keys 1-4 jump to ORBIT / FLY / TOUR / DRIVE from any mode.', 'Driver -> DRIVE, spectator free -> FLY, follow / menu -> CUSTOM.', 'Map "View in 3D" -> ORBIT at the selected place (drive.lookAt).']);
  return c;
};

D['07-data-pipeline'] = () => {
  const c = new Canvas(1620, 930, 'Build-time data pipeline (tools/*.mjs  ->  data/  ->  public/)');
  const col = (x, w, title, fill) => c.pkg(x, 70, w, 810, title, fill);
  col(30, 250, 'Sources (online)', '#f4f4f4');
  col(330, 300, 'Fetch tools, write data/', COL.tool + '88');
  col(680, 330, 'Build tools, write public/', COL.world + '77');
  col(1060, 530, 'Output: public/ (served + deployed)', COL.asset + '77');

  const src = [['OpenStreetMap', 'Overpass API'], ['AWS Terrain Tiles', 'elevation (Terrarium)'], ['Esri World Imagery', 'EOX Sentinel-2 (far)'], ['ambientCG', 'CC0 PBR texture sets'], ['Sketchfab downloads', 'BMW M2, McLaren P1, Countach']];
  const sy = [120, 240, 360, 480, 600];
  const sb = src.map(([t, l], i) => c.box(50, sy[i], 210, 80, { title: t, lines: [l], fill: COL.ext }));
  const fetchT = [['fetch-data.mjs', 'OSM + 5 m height grid'], ['fetch-region.mjs · fetch-far.mjs', 'fine OSM chunks, far LOD data'], ['fetch-imagery.mjs', 'aerial mosaics (z17 / z18 / z19)'], ['build-textures.mjs', 'PBR texture library + road field'], ['(manual download)', 'data/car/*.glb']];
  const fb = fetchT.map(([t, l], i) => c.box(350, sy[i], 260, 80, { title: t, lines: [l], fill: COL.tool, titleSize: 12.5 }));
  sb.forEach((s, i) => c.arrow([[s.r, s.cy], [fb[i].x, fb[i].cy]], { head: 'filled' }));
  const data = c.file(350, 730, 260, 110, { title: 'data/', fill: COL.asset, lines: ['osm.json, osm_far/, height.bin', 'tex_raw/, car/', 'landmark-skip.json'] });
  c.arrow([[480, 680], [480, 730]], { head: 'filled' });
  c.arrow([[data.r, data.cy], [680, data.cy]], { head: 'filled', label: 'read by', dy: -8 });

  const bt = [
    ['build-orbeli.mjs', 'map/orbeli.json'],
    ['build-landmarks.mjs', 'map/lm/footprints.json'],
    ['build-map.mjs', 'map/ meta, height, surface, colliders'],
    ['build-tiles.mjs + pack-tiles.mjs', 'tiles/ L0..L4 *.glb, pack34.bin'],
    ['build-props.mjs + clean-onroad.mjs', 'map/props.json (trees, lamps, neon)'],
    ['build-nav.mjs · build-circuits.mjs', 'map/nav.json, circuits.json'],
    ['build-car.mjs · build-car-pack.mjs', 'car/*.glb + *.json'],
    ['make-lowres.mjs', 'half-res *.2k.webp (Low / Med)'],
  ];
  const bb = bt.map(([t, l], i) => c.box(705, 110 + i * 95, 280, 70, { title: t, lines: [l], fill: COL.world, titleSize: 12 }));
  const out = [['map/', ['meta, props, nav, orbeli, surface,', 'colliders, circuits, lm/, aerial*.webp']], ['tiles/', ['L0..L4 *.glb, manifest.json, pack34.bin']], ['car/', ['bmw_m2, mclaren_p1, countach (*.glb + *.json)']], ['tex/', ['PBR sets, roadfield.png']]];
  const oy = [120, 270, 400, 530];
  out.forEach(([t, l], i) => c.file(1100, oy[i], 450, 110 - (i ? 20 : 0), { title: 'public/' + t, lines: l, fill: COL.asset }));
  c.arrow([[1010, 400], [1060, 400]], { head: 'filled', label: 'writes', dy: -8 });
  c.note(1100, 680, 450, ['npm run build:all = orbeli > landmarks > map > tiles >', 'props > clean-onroad > car > nav', 'public/ is committed: a fresh clone runs without', 'rebuilding anything.']);
  return c;
};

// ====================================================================================================================================
const want = process.argv[2];
for (const [name, fn] of Object.entries(D)) {
  if (want && !name.includes(want)) continue;
  const c = fn();
  const svg = c.svg();
  await sharp(Buffer.from(svg), { density: 192 }).png({ compressionLevel: 9 }).toFile(path.join(OUT, name + '.png'));
  console.log('wrote docs/img/' + name + '.png');
}
